    example: 'nums = [1, 2, 3, 4]\n\nsquares = (n * n for n in nums)\nprint(sum(squares))\n\nprint(sum(n for n in range(1, 101)))\nprint(max(len(w) for w in ["hi", "hello"]))\n\ndef countdown(n):\n    while n > 0:\n        yield n\n        n -= 1\n\nprint(list(countdown(4)))',
